<?php
 namespace App\Http\Middleware; use Closure; use Illuminate\Auth\AuthenticationException; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Log; use Symfony\Component\HttpKernel\Exception\UnauthorizedHttpException; use Tymon\JWTAuth\Exceptions\JWTException; use Tymon\JWTAuth\Http\Middleware\BaseMiddleware; use Tymon\JWTAuth\Exceptions\TokenExpiredException; class AuthenticateToken extends BaseMiddleware { private function checkTokenTime() { $user = $this->auth->user(); $issuedAtTime = $this->auth->manager()->getPayloadFactory()->buildClaimsCollection()->get('iat')->getValue(); if ($issuedAtTime < $user->remember_token) { return false; } return true; } public function handle($request, Closure $next) { if (is_string($request->query('token'))) { $request->headers->set('Authorization', $request->query('token')); } $this->checkForToken($request); try { if ($this->auth->parseToken()->authenticate()) { if ($this->checkTokenTime()) { return $next($request); } else { throw new UnauthorizedHttpException('jwt-auth', 'Token invalid'); } } else { throw new UnauthorizedHttpException('jwt-auth', 'User not found'); } } catch (TokenExpiredException $exception) { try { $token = $this->auth->refresh(); Auth::onceUsingId($this->auth->manager()->getPayloadFactory()->buildClaimsCollection()->get('sub')->getValue()); if ($this->checkTokenTime()) { return $this->setAuthenticationHeader($next($request), $token); } else { throw new UnauthorizedHttpException('jwt-auth', 'Token invalid'); } } catch (JWTException $exception) { throw new UnauthorizedHttpException('jwt-auth', $exception->getMessage()); } } catch (JWTException $exception) { throw new UnauthorizedHttpException('jwt-auth', $exception->getMessage()); } } }